/**
 * API returns instants like 2026-03-11T18:00:00Z; when the user picks a new calendar day,
 * keep the same UTC time-of-day as the previous value. Date-only values use 00:00:00.
 */
function formatHealthDateFieldForApi(datePart: string, existingApiValue: string): string {
  const s = existingApiValue.trim();
  let utcTime = '00:00:00';
  if (s) {
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
      utcTime = '00:00:00';
    } else {
      const parsed = moment.utc(s);
      if (parsed.isValid()) {
        utcTime = parsed.format('HH:mm:ss');
      }
    }
  }
  return `${datePart}T${utcTime}Z`;
}

